static int rtl_eee_enable(struct r8152 *tp, bool enable)
{
	int ret;

	switch (tp->version) {
	case RTL_VER_01:
	case RTL_VER_02:
	case RTL_VER_07:
		if (enable) {
			ret = r8152_eee_en(tp, true);
			if (ret < 0)
				goto out;
			ret = r8152_mmd_write(tp, MDIO_MMD_AN, MDIO_AN_EEE_ADV,
					      tp->eee_adv);
		} else {
			ret = r8152_eee_en(tp, false);
			if (ret < 0)
				goto out;
			ret = r8152_mmd_write(tp, MDIO_MMD_AN, MDIO_AN_EEE_ADV,
					      0);
		}
		break;
	case RTL_VER_03:
	case RTL_VER_04:
	case RTL_VER_05:
	case RTL_VER_06:
	case RTL_VER_08:
	case RTL_VER_09:
	case RTL_VER_14:
		ret = r8153_eee_en(tp, enable);
		break;
	case RTL_VER_10:
	case RTL_VER_11:
	case RTL_VER_12:
	case RTL_VER_13:
	case RTL_VER_15:
		ret = r8156_eee_en(tp, enable);
		break;
	case RTL_VER_16:
	case RTL_VER_17:
		ret = r8157_eee_en(tp, enable);
		break;
	default:
		ret = 0;
		WARN_ON_ONCE(1);
		break;
	}

out:
	return (ret < 0) ? ret : 0;
}
